# Seasonal public-domain tunes: Winter, Spring, Summer, Autumn, Halloween.
#
# Every melody here is public domain (traditional, or by a composer long dead and
# published before 1929) and was checked note by note against the source named
# above it.  No lyrics.  The accompaniments are generated by the engine from the
# chord symbols, so the arrangements are original.  Transpositions, excerpts and
# simplifications are stated in each tune's badges and note.
from tunes import tune

